import glob
import os
import sqlite3

# Load the map
files = glob.glob('/data/maps/*.Civ6Map')
db_path = files[0]

conn = sqlite3.connect(db_path)
conn.row_factory = sqlite3.Row
cursor = conn.cursor()

cursor.execute('SELECT Width, Height FROM Map')
map_info = cursor.fetchone()
width = map_info['Width']
height = map_info['Height']

cursor.execute('SELECT * FROM Plots')
plots = {row['ID']: dict(row) for row in cursor.fetchall()}

cursor.execute('SELECT ID, FeatureType FROM PlotFeatures')
features = {row['ID']: row['FeatureType'] for row in cursor.fetchall()}

cursor.execute('SELECT ID, RouteType FROM PlotRoutes')
routes = {row['ID']: row['RouteType'] for row in cursor.fetchall()}

cursor.execute('SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers')
rivers = {}
for row in cursor.fetchall():
    if row['IsNEOfRiver'] or row['IsWOfRiver'] or row['IsNWOfRiver']:
        rivers[row['ID']] = {
            'ne': row['IsNEOfRiver'],
            'w': row['IsWOfRiver'],
            'nw': row['IsNWOfRiver'],
        }

conn.close()

for pid, p in plots.items():
    p['X'] = pid % width
    p['Y'] = pid // width
    p['FeatureType'] = features.get(pid, '')
    p['RouteType'] = routes.get(pid, '')
    p['Rivers'] = rivers.get(pid, {})

land_tiles = []
for pid, p in plots.items():
    terrain = p.get('TerrainType', '')
    if terrain in ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_GRASS_MOUNTAIN', 'TERRAIN_COAST']:
        land_tiles.append({
            'x': p['X'], 'y': p['Y'],
            'terrain': terrain, 'feature': p['FeatureType'],
            'rivers': p['Rivers']
        })

def get_adjacent(x, y):
    dirs = [(0, -1), (1, -1), (1, 0), (0, 1), (-1, 1), (-1, 0)]
    adj = []
    for dx, dy in dirs:
        for t in land_tiles:
            if t['x'] == x + dx and t['y'] == y + dy:
                adj.append(t)
                break
    return adj

def get_radius(x, y, r=3):
    return [t for t in land_tiles if abs(t['x'] - x) <= r and abs(t['y'] - y) <= r]

# Best city center: (21, 14)
# It has: 1 mountain adjacent, 1 geothermal adjacent, 2 rivers adjacent
CITY_CENTER = (21, 14)

print("="*60)
print("CITY CENTER")
print("="*60)
print(f"Location: ({CITY_CENTER[0]}, {CITY_CENTER[1]})")

# Tiles within 3 tiles
radius = get_radius(*CITY_CENTER, 3)
available = [t for t in radius if not (t['x'] == CITY_CENTER[0] and t['y'] == CITY_CENTER[1])]

# Adjacency functions
def campus_bonus(tile):
    bonus = 0
    for t in get_adjacent(tile['x'], tile['y']):
        if t['terrain'] == 'TERRAIN_GRASS_MOUNTAIN':
            bonus += 2
        if t['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
            bonus += 1
    return bonus

def holy_bonus(tile):
    bonus = 0
    for t in get_adjacent(tile['x'], tile['y']):
        if t['terrain'] == 'TERRAIN_GRASS_MOUNTAIN':
            bonus += 2
        if t['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
            bonus += 2
    return bonus

def commercial_bonus(tile):
    bonus = 0
    for t in get_adjacent(tile['x'], tile['y']):
        if t['rivers']:
            bonus += 2
        if t['terrain'] == 'TERRAIN_COAST':
            bonus += 1
    return bonus

def encampment_bonus(tile):
    bonus = 0
    for t in get_adjacent(tile['x'], tile['y']):
        if t['terrain'] == 'TERRAIN_GRASS_MOUNTAIN':
            bonus += 2
    return bonus

def harbor_bonus(tile):
    if tile['terrain'] != 'TERRAIN_COAST':
        return 0
    bonus = 0
    for t in get_adjacent(tile['x'], tile['y']):
        if t['terrain'] in ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_GRASS_MOUNTAIN']:
            bonus += 1
    return bonus

# Calculate all options
options = {}
for t in available:
    key = (t['x'], t['y'])
    options[key] = {
        'tile': t,
        'CAMPUS': campus_bonus(t),
        'HOLY_SITE': holy_bonus(t),
        'COMMERCIAL_HUB': commercial_bonus(t),
        'ENCAMPMENT': encampment_bonus(t),
        'HARBOR': harbor_bonus(t),
    }

# Greedy selection
used = set()
placements = {}

for dtype in ['CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'ENCAMPMENT', 'HARBOR']:
    best = None
    best_adj = -1
    for key, opts in options.items():
        if key in used:
            continue
        if opts[dtype] > best_adj:
            best_adj = opts[dtype]
            best = key

    if best is not None:
        used.add(best)
        placements[dtype] = {
            'x': best[0],
            'y': best[1],
            'adjacency': best_adj
        }

print("\n" + "="*60)
print("DISTRICT PLACEMENTS")
print("="*60)

for dtype, p in placements.items():
    print(f"{dtype}: ({p['x']}, {p['y']}) - Adjacency: {p['adjacency']}")
    adj = get_adjacent(p['x'], p['y'])
    print("  Adjacent tiles:")
    for t in adj:
        reasons = []
        if t['terrain'] == 'TERRAIN_GRASS_MOUNTAIN':
            reasons.append("mountain")
        if t['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
            reasons.append("geothermal")
        if t['rivers']:
            reasons.append("river")
        if t['terrain'] == 'TERRAIN_COAST':
            reasons.append("coast")
        if t['terrain'] in ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_GRASS_MOUNTAIN']:
            reasons.append("land")
        print(f"    ({t['x']}, {t['y']}) {t['terrain'].replace('TERRAIN_','')} {t['feature'].replace('FEATURE_','')} -> {reasons}")

total = sum(p['adjacency'] for p in placements.values())
print(f"\nTotal Adjacency: {total}")

# Verify each calculation
print("\n" + "="*60)
print("VERIFICATION")
print("="*60)

# CAMPUS at (21, 12)
print("\nCAMPUS at (21, 12):")
campus_adj = get_adjacent(21, 12)
print(f"  Adjacent tiles: {[(t['x'], t['y']) for t in campus_adj]}")
campus_bonus_calc = 0
for t in campus_adj:
    if t['terrain'] == 'TERRAIN_GRASS_MOUNTAIN':
        campus_bonus_calc += 2
        print(f"    Mountain at ({t['x']}, {t['y']}) -> +2")
    if t['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
        campus_bonus_calc += 1
        print(f"    Geothermal at ({t['x']}, {t['y']}) -> +1")
print(f"  Total: {campus_bonus_calc}")

# HOLY_SITE at (22, 12)
print("\nHOLY_SITE at (22, 12):")
holy_adj_tiles = get_adjacent(22, 12)
print(f"  Adjacent tiles: {[(t['x'], t['y']) for t in holy_adj_tiles]}")
holy_bonus_calc = 0
for t in holy_adj_tiles:
    if t['terrain'] == 'TERRAIN_GRASS_MOUNTAIN':
        holy_bonus_calc += 2
        print(f"    Mountain at ({t['x']}, {t['y']}) -> +2")
    if t['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
        holy_bonus_calc += 2
        print(f"    Geothermal at ({t['x']}, {t['y']}) -> +2")
print(f"  Total: {holy_bonus_calc}")

# COMMERCIAL_HUB at (22, 16)
print("\nCOMMERCIAL_HUB at (22, 16):")
comm_adj_tiles = get_adjacent(22, 16)
print(f"  Adjacent tiles: {[(t['x'], t['y']) for t in comm_adj_tiles]}")
comm_bonus_calc = 0
for t in comm_adj_tiles:
    if t['rivers']:
        comm_bonus_calc += 2
        print(f"    River at ({t['x']}, {t['y']}) -> +2")
    if t['terrain'] == 'TERRAIN_COAST':
        comm_bonus_calc += 1
        print(f"    Coast at ({t['x']}, {t['y']}) -> +1")
print(f"  Total: {comm_bonus_calc}")

# ENCAMPMENT at (21, 11)
print("\nENCAMPMENT at (21, 11):")
enc_adj_tiles = get_adjacent(21, 11)
print(f"  Adjacent tiles: {[(t['x'], t['y']) for t in enc_adj_tiles]}")
enc_bonus_calc = 0
for t in enc_adj_tiles:
    if t['terrain'] == 'TERRAIN_GRASS_MOUNTAIN':
        enc_bonus_calc += 2
        print(f"    Mountain at ({t['x']}, {t['y']}) -> +2")
print(f"  Total: {enc_bonus_calc}")

# HARBOR at (20, 14)
print("\nHARBOR at (20, 14):")
harbor_adj_tiles = get_adjacent(20, 14)
print(f"  Adjacent tiles: {[(t['x'], t['y']) for t in harbor_adj_tiles]}")
harbor_bonus_calc = 0
for t in harbor_adj_tiles:
    if t['terrain'] in ['TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_GRASS_MOUNTAIN']:
        harbor_bonus_calc += 1
        print(f"    Land at ({t['x']}, {t['y']}) -> +1")
print(f"  Total: {harbor_bonus_calc}")

